sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({ api, event, helpers, imports }) {
    const date = new Date();
    const date_in = new Date(api.context.props.due_date);

    // Check if due_date is valid
    if (isNaN(date_in.getTime())) {
        console.warn("Invalid due_date:", api.context.props.due_date);
        return false;
    }

    return date >= date_in;
}
